const b = $json.body || $json;
const from = String(b.From || b.from || '').trim();
const bodyText = String(b.Body || b.body || '').trim();
const lower = bodyText.toLowerCase();
const trimmedLower = lower.trim();

// SMS compliance: standalone opt-out keywords (STOP, UNSUBSCRIBE, etc.) must NEVER be
// treated as an appointment-cancellation request and must NEVER trigger an automated
// reply — that would conflict with the customer's opt-out intent and carrier rules.
// Twilio's own Advanced Opt-Out feature may also intercept these at the carrier level
// before this workflow ever sees them; this check is a defense-in-depth backstop.
// Matched only when the ENTIRE message is an opt-out keyword (not a substring of a
// longer sentence like "please stop my service appointment" — which IS a cancel intent).
const isStandaloneOptOut = /^(stop|stopall|unsubscribe|cancel\s*all|quit|end|opt[\s-]?out|remove)[.!\s]*$/i.test(trimmedLower);

// Reschedule-confirmation replies (YES/NO) are short, standalone responses to WF13's
// "reply YES to confirm or NO if this doesn't work" SMS. Anchored to the whole message
// so longer sentences like "can't make it" still classify as cancel, not confirm_no.
const isConfirmYes = /^(y|yes|yep|yeah|yup|confirm|confirmed|sounds good|that works|works for me|ok|okay)[.!\s]*$/i.test(trimmedLower);
const isConfirmNo = /^(n|no|nope|nah)[.!\s]*$/i.test(trimmedLower);

let intent = 'other';
if (isStandaloneOptOut) {
  intent = 'other'; // silently ignored — no auto-reply sent to a likely opt-out message
} else if (/\b(cancel|cancelled|can't make it|cant make it|won't be able|wont be able)\b/.test(lower)) {
  intent = 'cancel';
} else if (/\b(reschedule|resched|change|move|different time|new time|push back|push it)\b/.test(lower)) {
  intent = 'reschedule';
} else if (isConfirmYes) {
  intent = 'confirm_yes';
} else if (isConfirmNo) {
  intent = 'confirm_no';
}

const raw = from.replace(/\D/g, '');
const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
  : raw.length === 10 ? '+1' + raw
  : (from.startsWith('+') ? from : null);

if (!e164) intent = 'other';

return [{ json: { fromPhone: from, e164Phone: e164, messageBody: bodyText, intent } }];

const inbound = $('Normalize Inbound SMS').first().json;
const appts = $input.all().map(i => i.json);

function normalizePhone(p) {
  const raw = String(p || '').replace(/\D/g, '');
  if (raw.length === 11 && raw.startsWith('1')) return raw.slice(1);
  return raw;
}

const inboundDigits = normalizePhone(inbound.fromPhone);
const isConfirmReply = inbound.intent === 'confirm_yes' || inbound.intent === 'confirm_no';

const candidates = appts.filter(a => {
  const status = (a['Status'] || '').trim();
  if (status !== 'Scheduled') return false;
  if (!(inboundDigits.length === 10 && normalizePhone(a['Phone']) === inboundDigits)) return false;
  if (isConfirmReply) {
    return String(a['Reschedule Status'] || '').trim() === 'Pending Customer Confirmation';
  }
  return true;
});

candidates.sort((a, b) => {
  const da = String(a['Appt Date'] || '');
  const db = String(b['Appt Date'] || '');
  if (da !== db) return da < db ? -1 : 1;
  return String(a['Appt Time'] || '').localeCompare(String(b['Appt Time'] || ''));
});

const appt = candidates[0];

if (!appt) {
  return [{ json: { found: false, intent: inbound.intent, fromPhone: inbound.fromPhone, e164Phone: inbound.e164Phone, messageBody: inbound.messageBody } }];
}

return [{ json: {
  found: true,
  intent: inbound.intent,
  fromPhone: inbound.fromPhone,
  e164Phone: inbound.e164Phone,
  messageBody: inbound.messageBody,
  apptId: appt['Appt ID'],
  leadId: appt['Lead ID'] || '',
  customerName: appt['Customer Name'] || '',
  serviceType: appt['Service Type'] || 'roofing appointment',
  apptDate: appt['Appt Date'] || '',
  apptTime: appt['Appt Time'] || '',
  existingNotes: appt['Notes'] || '',
  rescheduleStatus: appt['Reschedule Status'] || 'None',
  rescheduleAttempts: Number(appt['Reschedule Attempts'] || 0)
} }];

const CONFIG = {
  COMPANY_NAME: 'Valfin Tech',
  COMPANY_PHONE: '(857) 526-1499',
  OWNER_PHONE: '+18575261499',
  OWNER_EMAIL: 'valfintechnologies@gmail.com',
  TWILIO_FROM_NUMBER: '+18889839308',
  EMAIL_ALERTS_ENABLED: true,
  SMS_ALERTS_ENABLED: false,
  DEFAULT_TIMEZONE: 'America/New_York'
};

const d = $json;
const firstName = String(d.customerName || '').trim().split(/\s+/)[0] || '';
const greeting = firstName ? 'Hi ' + firstName + ',' : 'Hi,';
const svc = d.serviceType || 'roofing appointment';
const who = d.customerName || d.fromPhone;

const ts = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toISO();

let customerReply = '';
let ownerAlert = '';
let ownerEmailSubject = '';
let ownerEmailHtml = '';
let newStatus = 'Scheduled';
let newRescheduleStatus = String(d.rescheduleStatus || 'None');
let newRescheduleAttempts = Number(d.rescheduleAttempts || 0);
let notesAppend = '';
let sendOwnerSms = false;
let sendOwnerEmail = false;
let shouldLogCommunication = false;
let logDirection = '';
let logSummary = '';
let logNotes = '';

if (d.intent === 'cancel') {
  customerReply = greeting + ' your ' + svc + ' appointment with Valfin Tech (' + d.apptDate + ' at ' + d.apptTime + ') has been cancelled per your request. Want to rebook? Just call us anytime.';
  ownerAlert = 'CANCELLATION via SMS: ' + who + ' (' + d.fromPhone + ') cancelled appt ' + d.apptId + ' — ' + d.apptDate + ' at ' + d.apptTime + ' (' + svc + '). Consider following up to rebook.';
  newStatus = 'Cancelled';
  notesAppend = '[' + ts + '] Customer cancelled via SMS reply: "' + d.messageBody + '"';
  sendOwnerSms = true;
} else if (d.intent === 'reschedule') {
  customerReply = greeting + ' thanks for letting us know — we got your reschedule request for your ' + svc + ' appointment (' + d.apptDate + ' at ' + d.apptTime + '). Our team will call you shortly to find a new time. You can also call us anytime.';
  ownerAlert = 'RESCHEDULE REQUEST via SMS: ' + who + ' (' + d.fromPhone + ') wants to reschedule appt ' + d.apptId + ' — currently ' + d.apptDate + ' at ' + d.apptTime + ' (' + svc + '). Please call them to confirm a new time.';
  newStatus = 'Scheduled';
  notesAppend = '[' + ts + '] Customer requested reschedule via SMS reply: "' + d.messageBody + '"';
  sendOwnerSms = true;
} else if (d.intent === 'confirm_yes') {
  customerReply = '';
  newRescheduleStatus = 'Confirmed';
  notesAppend = '[' + ts + '] Customer confirmed rescheduled appointment via SMS reply: "' + d.messageBody + '"';
  ownerAlert = who + ' confirmed the updated appointment (' + d.apptDate + ' at ' + d.apptTime + ').';
  ownerEmailSubject = who + ' confirmed the updated appointment';
  ownerEmailHtml = '<p>' + who + ' confirmed the updated appointment.</p><p>Appointment <strong>' + d.apptId + '</strong> — ' + d.apptDate + ' at ' + d.apptTime + ' (' + svc + ').</p>';
  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
  shouldLogCommunication = true;
  logDirection = 'Inbound';
  logSummary = 'Reschedule Confirmation';
  logNotes = d.messageBody;
} else if (d.intent === 'confirm_no') {
  newRescheduleAttempts = Number(d.rescheduleAttempts || 0) + 1;
  shouldLogCommunication = true;
  logDirection = 'Inbound';
  logSummary = 'Customer Requested Different Time';
  logNotes = d.messageBody;

  if (newRescheduleAttempts >= 2) {
    newRescheduleStatus = 'Manual Follow-Up Required';
    customerReply = 'We want to make sure we find the best time for you. Please give us a call at ' + CONFIG.COMPANY_PHONE + ', or we will reach out shortly to coordinate directly.';
    ownerAlert = who + ' has exceeded automated rescheduling attempts. Please contact them directly.';
    ownerEmailSubject = who + ' has exceeded automated rescheduling attempts';
    ownerEmailHtml = '<p>' + who + ' has exceeded automated rescheduling attempts (appt ' + d.apptId + ', currently ' + d.apptDate + ' at ' + d.apptTime + '). Please contact them directly.</p>';
    notesAppend = '[' + ts + '] Customer declined proposed time again via SMS reply (attempt ' + newRescheduleAttempts + '), escalated to manual follow-up: "' + d.messageBody + '"';
  } else {
    newRescheduleStatus = 'Customer Requested Different Time';
    customerReply = 'No problem. A member of our team will contact you shortly to help find a time that works best for you.';
    ownerAlert = who + ' cannot make the proposed appointment. Please contact them to finalize scheduling.';
    ownerEmailSubject = who + ' cannot make the proposed appointment';
    ownerEmailHtml = '<p>' + who + ' cannot make the proposed appointment (appt ' + d.apptId + ', currently ' + d.apptDate + ' at ' + d.apptTime + '). Please contact them to finalize scheduling.</p>';
    notesAppend = '[' + ts + '] Customer declined proposed time via SMS reply: "' + d.messageBody + '"';
  }

  sendOwnerEmail = CONFIG.EMAIL_ALERTS_ENABLED;
  sendOwnerSms = CONFIG.SMS_ALERTS_ENABLED;
}

const updatedNotes = (d.existingNotes ? d.existingNotes + ' | ' : '') + notesAppend;

return [{ json: {
  apptId: d.apptId,
  leadId: d.leadId || '',
  customerReply,
  hasCustomerReply: customerReply !== '',
  ownerAlert,
  ownerEmailSubject,
  ownerEmailHtml,
  newStatus,
  newRescheduleStatus,
  newRescheduleAttempts,
  updatedNotes,
  e164Phone: d.e164Phone,
  ownerPhone: CONFIG.OWNER_PHONE,
  ownerEmail: CONFIG.OWNER_EMAIL,
  from: CONFIG.TWILIO_FROM_NUMBER,
  sendOwnerSms,
  sendOwnerEmail,
  shouldLogCommunication,
  logChannel: 'SMS',
  logDirection,
  logHandler: 'Customer',
  logSummary,
  logNotes
} }];
